demo.css:
p { font: 700 32px/1.6 var(--demo-sans); margin: 8px 0; }
a, s {
  color: var(--demo-fg);
  text-decoration-thickness: 3px;
  text-decoration-color: var(--demo-accent);
  text-decoration-inset: var(--inset);
  transition: text-decoration-inset .3s;
}
a { text-decoration-line: underline; text-underline-offset: 6px; }
a:hover { text-decoration-inset: 0px; }
.s { font-size: 22px; }

fallback.css:
p { font: 700 32px/1.6 var(--demo-sans); margin: 8px 0; }
a {
  color: var(--demo-fg);
  text-decoration: none;
  background-image: linear-gradient(var(--demo-muted), var(--demo-muted));
  background-size: calc(100% - var(--inset) * 2) 3px;
  background-position: center bottom;
  background-repeat: no-repeat;
  padding-bottom: 4px;
}

before.code:
a {
  text-decoration: none;
  background-image: linear-gradient(currentColor, currentColor);
  background-size: calc(100% - 20px) 1px;
  background-position: center bottom;
  background-repeat: no-repeat;
  padding-bottom: 2px;
}
